Create Encounter.code:
// Create an outpatient Encounter for a patient visit.
// The adaptor prefixes the path with fhir-r4/v1 on the credential's baseUrl.
post('Encounter', {
  resourceType: 'Encounter',
  identifier: [
    {
      // Your organization's local encounter id.
      system: `http://sys-ids.kemkes.go.id/encounter/${$.configuration.organizationId}`,
      value: $.data.visitId,
    },
  ],
  status: 'arrived',
  // SATUSEHAT expects the status history alongside the current status.
  statusHistory: [{ status: 'arrived', period: { start: $.data.arrivedAt } }],
  class: {
    system: 'http://terminology.hl7.org/CodeSystem/v3-ActCode',
    code: 'AMB',
    display: 'ambulatory',
  },
  subject: { reference: `Patient/${$.data.patientIhsId}`, display: $.data.patientName },
  participant: [
    {
      type: [
        {
          coding: [
            {
              system: 'http://terminology.hl7.org/CodeSystem/v3-ParticipationType',
              code: 'ATND',
              display: 'attender',
            },
          ],
        },
      ],
      individual: { reference: `Practitioner/${$.data.practitionerIhsId}` },
    },
  ],
  period: { start: $.data.arrivedAt },
  location: [{ location: { reference: `Location/${$.data.locationId}` } }],
  serviceProvider: { reference: `Organization/${$.configuration.organizationId}` },
});

Create Observation.code:
// Record a body temperature Observation for an encounter.
post('Observation', {
  resourceType: 'Observation',
  status: 'final',
  category: [
    {
      coding: [
        {
          system: 'http://terminology.hl7.org/CodeSystem/observation-category',
          code: 'vital-signs',
        },
      ],
    },
  ],
  code: {
    coding: [{ system: 'http://loinc.org', code: '8310-5', display: 'Body temperature' }],
  },
  subject: { reference: `Patient/${$.data.patientIhsId}` },
  encounter: { reference: `Encounter/${$.data.encounterId}` },
  effectiveDateTime: $.data.measuredAt,
  valueQuantity: {
    value: $.data.temperature,
    unit: 'C',
    system: 'http://unitsofmeasure.org',
    code: 'Cel',
  },
});

Create Condition.code:
// Record an ICD-10 diagnosis for an encounter.
post('Condition', {
  resourceType: 'Condition',
  clinicalStatus: {
    coding: [
      {
        system: 'http://terminology.hl7.org/CodeSystem/condition-clinical',
        code: 'active',
      },
    ],
  },
  category: [
    {
      coding: [
        {
          system: 'http://terminology.hl7.org/CodeSystem/condition-category',
          code: 'encounter-diagnosis',
        },
      ],
    },
  ],
  code: {
    coding: [{ system: 'http://hl7.org/fhir/sid/icd-10', code: 'A09', display: 'Diarrhoea and gastroenteritis' }],
  },
  subject: { reference: `Patient/${$.data.patientIhsId}` },
  encounter: { reference: `Encounter/${$.data.encounterId}` },
});

Create Immunization.code:
// Report a vaccination given at the facility.
post('Immunization', {
  resourceType: 'Immunization',
  status: 'completed',
  vaccineCode: {
    coding: [{ system: 'http://sys-ids.kemkes.go.id/kfa', code: $.data.kfaCode, display: $.data.vaccineName }],
  },
  patient: { reference: `Patient/${$.data.patientIhsId}` },
  encounter: { reference: `Encounter/${$.data.encounterId}` },
  occurrenceDateTime: $.data.givenAt,
  lotNumber: $.data.lotNumber,
  performer: [{ actor: { reference: `Practitioner/${$.data.practitionerIhsId}` } }],
  protocolApplied: [{ doseNumberPositiveInt: $.data.doseNumber }],
});

Update Encounter Status.code:
// Mark an encounter as finished using a JSON Patch.
patch(
  // 1) Resource type and id.
  `Encounter/${$.data.encounterId}`,
  // 2) JSON Patch operations.
  [
    { op: 'replace', path: '/status', value: 'finished' },
    { op: 'add', path: '/period/end', value: $.data.dischargedAt },
  ]
);

Create Location.code:
// Register a clinic room as a Location under your organization.
post('Location', {
  resourceType: 'Location',
  identifier: [
    {
      system: `http://sys-ids.kemkes.go.id/location/${$.configuration.organizationId}`,
      value: $.data.roomCode,
    },
  ],
  status: 'active',
  name: $.data.roomName, // e.g. 'Poli Umum'
  mode: 'instance',
  physicalType: {
    coding: [{ system: 'http://terminology.hl7.org/CodeSystem/location-physical-type', code: 'ro', display: 'Room' }],
  },
  managingOrganization: { reference: `Organization/${$.configuration.organizationId}` },
});

Find Patient By NIK.code:
// Find a patient by national identity number (NIK).
get('Patient', {
  identifier: `https://fhir.kemkes.go.id/id/nik|${$.data.nik}`,
});

Find Practitioner By NIK.code:
// Find a practitioner by NIK to get their IHS number.
get('Practitioner', {
  identifier: `https://fhir.kemkes.go.id/id/nik|${$.data.practitionerNik}`,
});

Get Patient Encounters.code:
// List a patient's encounters.
get('Encounter', {
  subject: $.data.patientIhsId, // the patient's IHS id
  _count: 50,
});

Get Encounter Observations.code:
// List observations recorded in one encounter.
get('Observation', {
  encounter: $.data.encounterId,
  _count: 100,
});
